package app.meydan;
import android.Manifest;import android.app.*;import android.bluetooth.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.os.*;import android.view.*;import android.webkit.*;
import org.json.*;import org.java_websocket.client.WebSocketClient;import org.java_websocket.handshake.ServerHandshake;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import javax.net.ssl.*;
public class MainActivity extends Activity {
 private WebView web;private final ExecutorService tasks=Executors.newCachedThreadPool();private final ExecutorService writes=Executors.newSingleThreadExecutor();private final Map<String,Channel> peers=new ConcurrentHashMap<>();private ServerSocket tcpServer;private BluetoothServerSocket btServer;private WebSocketClient relay;private volatile int generation=0;private String deferred;private String exportContent;
 public static final UUID SERVICE=UUID.fromString("7591c0c6-2f53-4f19-a904-bef577040ba2");
 interface Closer{void close() throws IOException;}
 static class Channel {final OutputStream out;final Closer closer;Channel(OutputStream out,Closer closer){this.out=out;this.closer=closer;}synchronized void send(String line)throws IOException{if(line.getBytes(StandardCharsets.UTF_8).length>FrameReader.MAX||line.contains("\n"))throw new IOException("Invalid frame");out.write((line+"\n").getBytes(StandardCharsets.UTF_8));out.flush();}}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);web=new WebView(this);setContentView(web);web.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets i=insets.getInsets(WindowInsets.Type.systemBars());v.setPadding(i.left,i.top,i.right,i.bottom);}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});web.setBackgroundColor(0xff10151d);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setAllowFileAccessFromFileURLs(false);s.setAllowUniversalAccessFromFileURLs(false);web.addJavascriptInterface(new Bridge(),"Android");web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){return !r.getUrl().toString().startsWith("file:///android_asset/");}});web.setWebChromeClient(new WebChromeClient(){@Override public boolean onJsConfirm(WebView v,String url,String msg,JsResult r){new AlertDialog.Builder(MainActivity.this).setMessage(msg).setPositiveButton("تأكيد",(d,x)->r.confirm()).setNegativeButton("إلغاء",(d,x)->r.cancel()).setOnCancelListener(d->r.cancel()).show();return true;}@Override public boolean onJsPrompt(WebView v,String url,String msg,String def,JsPromptResult r){android.widget.EditText input=new android.widget.EditText(MainActivity.this);input.setText(def);new AlertDialog.Builder(MainActivity.this).setMessage(msg).setView(input).setPositiveButton("حفظ",(d,x)->r.confirm(input.getText().toString())).setNegativeButton("إلغاء",(d,x)->r.cancel()).show();return true;}@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> callback,FileChooserParams params){fileCallback=callback;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,32);return true;}});web.loadUrl("file:///android_asset/index.html");}
 private ValueCallback<Uri[]> fileCallback;
 class Bridge {@JavascriptInterface public void command(String json){if(json.length()>6000000)return;writes.execute(()->{try{JSONObject c=new JSONObject(json);String a=c.optString("action");if(a.equals("send"))execute(json);else tasks.execute(()->execute(json));}catch(Exception ignored){}});}}
 private JSONObject obj(String type){JSONObject e=new JSONObject();try{e.put("type",type);}catch(Exception ignored){}return e;}
 private void emit(JSONObject e){runOnUiThread(()->web.evaluateJavascript("window.meydanEvent("+e.toString()+")",null));}
 private void error(String m){JSONObject e=obj("error");try{e.put("message",m);}catch(Exception ignored){}emit(e);}
 private BluetoothAdapter adapter()throws Exception{BluetoothManager m=(BluetoothManager)getSystemService(BLUETOOTH_SERVICE);BluetoothAdapter a=m==null?null:m.getAdapter();if(a==null)throw new IOException("هذا الجهاز لا يحتوي على بلوتوث. اختر الشبكة المحلية.");if(!a.isEnabled())throw new IOException("فعّل البلوتوث من إعدادات الجهاز أولًا.");return a;}
 private boolean permission(String json){if(Build.VERSION.SDK_INT>=31&&(checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT)!=PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.BLUETOOTH_SCAN)!=PackageManager.PERMISSION_GRANTED)){deferred=json;runOnUiThread(()->requestPermissions(new String[]{Manifest.permission.BLUETOOTH_CONNECT,Manifest.permission.BLUETOOTH_SCAN},31));return false;}return true;}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==31){String d=deferred;deferred=null;if(results.length>=2&&results[0]==PackageManager.PERMISSION_GRANTED&&results[1]==PackageManager.PERMISSION_GRANTED){if(d!=null)tasks.execute(()->execute(d));}else error("لم تُمنح صلاحية البلوتوث. يمكنك منحها من الإعدادات أو استخدام الشبكة.");}}
 private void execute(String json){try{JSONObject c=new JSONObject(json);String action=c.getString("action");if(action.equals("stop")){stop();return;}if(action.equals("send")){String id=c.getString("peerId"),line=c.getString("line");if(line.getBytes(StandardCharsets.UTF_8).length>FrameReader.MAX)throw new IOException("الرسالة كبيرة جدًا");if(relay!=null&&relay.isOpen()){relay.send(new JSONObject().put("type","send").put("peerId",id).put("line",line).toString());return;}Channel ch=peers.get(id);if(ch!=null)ch.send(line);return;}if(action.equals("export")){exportContent=c.getString("content");String name=c.getString("name");runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(i,33);});return;}String mode=c.optString("mode");if(action.equals("devices")||mode.equals("bt")){if(!permission(json))return;}if(action.equals("devices")){JSONArray list=new JSONArray();for(BluetoothDevice d:adapter().getBondedDevices())list.put(new JSONObject().put("name",d.getName()).put("address",d.getAddress()));emit(obj("devices").put("devices",list));return;}stop();int epoch=generation;boolean host=action.equals("host");if(mode.equals("online")){openRelay(c,host,epoch);return;}if(host){if(mode.equals("bt")){btServer=adapter().listenUsingRfcommWithServiceRecord("Meydan Challenge",SERVICE);BluetoothServerSocket server=btServer;emit(obj("hosting").put("address","Bluetooth · "+adapter().getName()));while(epoch==generation){BluetoothSocket s=server.accept();attach(UUID.randomUUID().toString(),s.getInputStream(),s.getOutputStream(),s::close,epoch,false);}}else{tcpServer=new ServerSocket();tcpServer.setReuseAddress(true);tcpServer.bind(new InetSocketAddress(45871));ServerSocket server=tcpServer;emit(obj("hosting").put("address",addresses()+":45871"));while(epoch==generation){Socket s=server.accept();s.setTcpNoDelay(true);s.setSoTimeout(30000);attach(UUID.randomUUID().toString(),s.getInputStream(),s.getOutputStream(),s::close,epoch,false);}}}else{String address=c.getString("address");if(mode.equals("bt")){BluetoothAdapter a=adapter();a.cancelDiscovery();BluetoothSocket s=a.getRemoteDevice(address).createRfcommSocketToServiceRecord(SERVICE);try{s.connect();attach("host",s.getInputStream(),s.getOutputStream(),s::close,epoch,true);}catch(Exception ex){s.close();throw ex;}}else{String[] parts=address.split(":");Socket s=new Socket();s.connect(new InetSocketAddress(parts[0],parts.length>1?Integer.parseInt(parts[1]):45871),10000);s.setTcpNoDelay(true);s.setSoTimeout(30000);attach("host",s.getInputStream(),s.getOutputStream(),s::close,epoch,true);}}}catch(Exception ex){error("تعذر الاتصال: "+ex.getMessage());}}
 private void attach(String id,InputStream in,OutputStream out,Closer close,int epoch,boolean client)throws Exception{if(epoch!=generation){close.close();return;}Channel ch=new Channel(out,close);peers.put(id,ch);emit(obj(client?"connected":"peer").put("peerId",id));tasks.execute(()->{try{String line;while(epoch==generation&&(line=FrameReader.read(in))!=null){emit(obj("line").put("peerId",id).put("line",line));}}catch(Exception ignored){}finally{boolean removed=peers.remove(id,ch);try{close.close();}catch(Exception ignored){}try{if(removed&&epoch==generation)emit(obj("disconnected").put("peerId",id));}catch(Exception ignored){}}});}
 private String addresses(){try{for(NetworkInterface n:Collections.list(NetworkInterface.getNetworkInterfaces()))for(InetAddress a:Collections.list(n.getInetAddresses()))if(!a.isLoopbackAddress()&&a instanceof Inet4Address)return a.getHostAddress();}catch(Exception ignored){}return "عنوان IP من إعدادات الشبكة";}
 private void openRelay(JSONObject c,boolean host,int epoch)throws Exception{String url=host?c.getString("relay"):c.getString("address");URI uri=new URI(url);if(!"wss".equals(uri.getScheme()))throw new IOException("يجب استخدام wss لاتصال الإنترنت");relay=new WebSocketClient(uri){@Override public void onOpen(ServerHandshake h){try{send(new JSONObject().put("type","register").put("role",host?"host":"player").put("room",c.getString("room")).put("key",host?c.optString("key"):"").toString());}catch(Exception ex){error(ex.getMessage());}}@Override public void onMessage(String line){if(epoch!=generation||line.length()>140000)return;try{JSONObject m=new JSONObject(line);String t=m.optString("type");if(t.equals("ready"))emit(obj(host?"hosting":"connected").put("address","Internet"));else if(t.equals("data"))emit(obj("line").put("peerId",m.optString("peerId","host")).put("line",m.getString("line")));else if(t.equals("peer")||t.equals("disconnected"))emit(m);else if(t.equals("error"))error(m.optString("reason"));}catch(Exception ex){error("رسالة ترحيل غير صالحة");}}@Override public void onClose(int code,String reason,boolean remote){if(epoch==generation)emit(obj("disconnected"));}@Override public void onError(Exception ex){if(epoch==generation)error(ex.getMessage());}};SSLSocketFactory ssl=(SSLSocketFactory)SSLSocketFactory.getDefault();SSLSocket socket=(SSLSocket)ssl.createSocket();SSLParameters p=socket.getSSLParameters();p.setEndpointIdentificationAlgorithm("HTTPS");socket.setSSLParameters(p);relay.setSocket(socket);relay.setConnectionLostTimeout(15);relay.connect();}
 private synchronized void stop(){generation++;try{if(tcpServer!=null)tcpServer.close();}catch(Exception ignored){}tcpServer=null;try{if(btServer!=null)btServer.close();}catch(Exception ignored){}btServer=null;if(relay!=null){relay.close();relay=null;}for(Channel c:peers.values())try{c.closer.close();}catch(Exception ignored){}peers.clear();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==32&&fileCallback!=null){fileCallback.onReceiveValue(result==RESULT_OK&&data!=null?new Uri[]{data.getData()}:null);fileCallback=null;}if(request==33&&result==RESULT_OK&&data!=null){Uri uri=data.getData();String value=exportContent;exportContent=null;tasks.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(uri)){out.write(value.getBytes(StandardCharsets.UTF_8));}catch(Exception ex){error("تعذر تصدير الملف");}});}}
 @Override public void onBackPressed(){web.evaluateJavascript("document.getElementById('leave').click()",null);}
 @Override protected void onDestroy(){stop();tasks.shutdownNow();writes.shutdownNow();web.destroy();super.onDestroy();}
}
